import { Catalog, Category, ErrorEvent, Identity, PartyIdentification } from '../events';
/**
Description: Stop viewing the details of a product (e.g. a Product Detail Page). This does not cover the case where a product impression is viewed as part of a list (e.g., a Product Listing Page). This interaction is for tracking how much time a shopper spends viewing the details of a product. It is considered optional and may or may not be implemented. If sent, it must be preceded by a corresponding Product View Start interaction.
*/
export type ProductViewStop = {
    events: Array<Catalog | Identity | PartyIdentification | ErrorEvent>;
}

export class ProductViewStopBuilder {

    private productViewStop: ProductViewStop = {
        events: []
    }

    private catalog!: Catalog;
    private errorEvent!: ErrorEvent;
    private identity!: Identity;
    private partyIdentification!: PartyIdentification;

    public withCatalog(catalog: Catalog) : ProductViewStopBuilder {
        this.catalog = catalog;
        return this;
    }
    public withErrorEvent(errorEvent: ErrorEvent) : ProductViewStopBuilder {
        this.errorEvent = errorEvent;
        return this;
    }
    public withIdentity(identity: Identity) : ProductViewStopBuilder {
        this.identity = identity;
        return this;
    }
    public withPartyIdentification(partyIdentification: PartyIdentification) : ProductViewStopBuilder {
        this.partyIdentification = partyIdentification;
        return this;
    }

    public build() : ProductViewStop {
        if(this.catalog) {
            this.productViewStop.events.push(this.catalog);
        }
        if(this.errorEvent) {
            this.productViewStop.events.push(this.errorEvent);
        }
        if(this.identity) {
            this.productViewStop.events.push(this.identity);
        }
        if(this.partyIdentification) {
            this.productViewStop.events.push(this.partyIdentification);
        }

        return this.productViewStop;
    }
}
